        .decoration-2 { top: 15%; right: 7%; animation: float 9s ease-in-out infinite 1s; }
        .decoration-3 { bottom: 12%; left: 8%; animation: float 8s ease-in-out infinite 2s; }
        .decoration-4 { bottom: 18%; right: 5%; animation: float 10s ease-in-out infinite 3s; }

        /* 演变容器样式 */
