            max-width: 850px;
            background: var(--evolution-bg);
            border-radius: 16px;
            box-shadow: 0 8px 30px var(--evolution-shadow);
            overflow: hidden;
            margin: 0 auto 12px;
            position: relative;
            border: 1px solid var(--evolution-border);
