            pointer-events: none;
            z-index: 0;
        }

        .evolution-header {
            background: var(--evolution-header-bg);
            padding: 12px;
            text-align: center;
            position: relative;
            cursor: pointer;
            box-shadow: 0 3px 12px rgba(0,0,0,0.2);
            overflow: hidden;
            display: flex;
            justify-content: center;
            align-items: center;
        }

        .evolution-header::before {
            content: '';
            position: absolute;
            top: 0; left: 0; right: 0; bottom: 0;
            background: linear-gradient(90deg, transparent, rgba(255,71,160,0.2), transparent);
            animation: shimmer 4s infinite;
            transform: translateX(-100%);
            pointer-events: none;
        }

        .evolution-header h2 {
            font-size: 1.8rem;
            font-weight: 600;
            margin: 0;
            color: var(--evolution-text-primary);
            text-shadow: 0 2px 4px rgba(0,0,0,0.3);
        }

        .evolution-arrow {
            color: var(--evolution-text-primary);
            font-size: 1.5rem;
            position: absolute;
            right: 20px;
            transition: transform 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
        }

        .evolution-header.collapsed .evolution-arrow {
            transform: rotate(-90deg);
        }

        .evolution-body {
            padding: 0;
            max-height: 0;
            overflow: hidden;
            transition: max-height 0.8s cubic-bezier(0.22, 0.61, 0.36, 1), padding 0.4s;
        }

        .evolution-body.expanded {
            max-height: 2000px;
            padding: 12px;
        }

        .evolution-section {
            margin-bottom: 12px;
        }

        .evolution-section-title {
            color: var(--evolution-accent);
            font-size: 1.4rem;
            margin-bottom: 8px;
            padding-bottom: 5px;
            border-bottom: 1px solid var(--evolution-border);
            text-shadow: 0 0 10px rgba(255,71,160,0.3);
        }

        .evolution-event {
            background-color: var(--evolution-card-bg);
            border-radius: 10px;
            padding: 8px;
            margin-bottom: 8px;
            border: 1px solid var(--evolution-border);
            position: relative;
            overflow: hidden;
            transition: all 0.3s;
            backdrop-filter: blur(5px);
        }

        .evolution-event::before {
            content: '';
            position: absolute;
            top: 0; left: 0; width: 100%; height: 100%;
            background: linear-gradient(135deg, transparent 0%, var(--evolution-highlight) 100%);
            opacity: 0;
            transition: opacity 0.3s;
        }

        .evolution-event:hover {
            transform: translateY(-3px);
            box-shadow: 0 5px 15px rgba(87, 19, 82, 0.3);
