        .evolution-indicator {
            display: inline-block;
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background-color: var(--evolution-accent);
            margin-right: 10px;
            vertical-align: middle;
            box-shadow: 0 0 8px var(--evolution-accent);
            animation: glow 1.5s infinite alternate;
        }

        @keyframes glow {
            0% { box-shadow: 0 0 5px var(--evolution-accent); }
            100% { box-shadow: 0 0 12px var(--evolution-accent), 0 0 20px rgba(255,71,160,0.3); }
        }

        /* 切换按钮样式 - 修改后 */
        .view-toggle-btn {
            position: absolute;
            top: 15px;
            right: 15px;
            background: linear-gradient(135deg, #2c0505 0%, #800000 100%);
            color: #fff;
            border: none;
            border-radius: 50%;
            width: 50px;
            height: 50px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 28px; /* 放大表情符号 */
            cursor: pointer;
            box-shadow: 0 3px 10px rgba(0,0,0,0.3);
            z-index: 10;
            transition: all 0.3s ease;
            animation: evil-pulse 2s infinite alternate;
        }

        /* 新增恶魔表情动画效果 */
        @keyframes evil-pulse {
            0% { transform: scale(1); box-shadow: 0 3px 10px rgba(0,0,0,0.3); }
            100% { transform: scale(1.1); box-shadow: 0 5px 15px rgba(196, 30, 58, 0.5); }
        }

        .view-toggle-btn:hover {
            transform: scale(1.2) !important;
            box-shadow: 0 5px 20px rgba(196, 30, 58, 0.7) !important;
        }

        /* 邪恶视角样式 */
        .evil-view-container {
            display: none;
            max-width: 850px;
            margin: 0 auto;
            background-color: var(--evil-bg);
