        }

        .evil-view-title {
            color: #fff;
            font-size: 1.8rem;
            text-align: center;
            margin: 0;
            text-shadow: 0 2px 4px rgba(0,0,0,0.5);
        }

        .evil-view-content {
            padding: 20px;
        }

        .evil-perspective {
            background-color: var(--evil-card-bg);
            border-radius: 8px;
            padding: 15px;
            margin-bottom: 15px;
            border-left: 4px solid var(--evil-accent);
